/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::NOT_SEALED_MODE,
    error_codes::CANNOT_OPEN,
    error_codes::INVALID_CREDENTIAL,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vtc/storage/credentials/set:notFound`
    ///
    /// The community has no storage config with this identifier.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/storage/credentials/set:notFound",
        retryable: false,
    };
    /// `vtc/storage/credentials/set:notSealedMode`
    ///
    /// The config's `auth.mode` is not `sealed`. Credentials for a `vta-account` config are the VTA's, set there; an `ambient` config has none.
    ///
    /// Declared `retryable: false`.
    pub const NOT_SEALED_MODE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/storage/credentials/set:notSealedMode",
        retryable: false,
    };
    /// `vtc/storage/credentials/set:cannotOpen`
    ///
    /// The sealed block is not sealed to this community, is malformed, or its digest does not match `digestMultibase`. Nothing was stored.
    ///
    /// Declared `retryable: false`.
    pub const CANNOT_OPEN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/storage/credentials/set:cannotOpen",
        retryable: false,
    };
    /// `vtc/storage/credentials/set:invalidCredential`
    ///
    /// The block opened, but what it carries is not a credential for the config's kind (see Definitions). Nothing was stored.
    ///
    /// Declared `retryable: false`.
    pub const INVALID_CREDENTIAL: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/storage/credentials/set:invalidCredential",
        retryable: false,
    };
}
